using System;using System.IO;using System.IO.Compression;using UnityEngine;using System.Runtime.CompilerServices;using UnityEngine.Serialization;
// Binary curves reconstruct the original Unity AnimationCurve evaluator, without re-keying.
public sealed class NativeSupportPoseData:ScriptableObject {
 [Serializable]public sealed class Joint {public string path;public AnimationCurve px,py,pz,qx,qy,qz,qw,sx,sy,sz;}
 public string sourceName,sourceCurveHash;public float duration;
 [FormerlySerializedAs("joints"),SerializeField]Joint[] legacyJoints;
 [SerializeField]TextAsset packedAsset;[SerializeField]string[] packedPaths;
 [NonSerialized]Joint[] decoded;[NonSerialized]int users;
 public bool IsDecoded=>decoded!=null;public int ActiveUsers=>users;public void Acquire(){users++;}public void Release(){if(users>0)users--;if(users==0)decoded=null;}
 public TextAsset PackedAsset=>packedAsset;
 public string[] JointPaths=>packedAsset?packedPaths:Array.ConvertAll(legacyJoints,j=>j.path);
 public Joint[] joints {get{if(legacyJoints!=null&&legacyJoints.Length>0)return legacyJoints;if(decoded==null)decoded=Decode();return decoded;}set{legacyJoints=value;packedAsset=null;packedPaths=null;decoded=null;}}
 public void SetPacked(TextAsset asset,string[] paths){packedAsset=asset;packedPaths=paths;legacyJoints=null;decoded=null;}
 public void ReleaseDecoded(){if(users>0)throw new InvalidOperationException("Native curves have active users");decoded=null;}
 sealed class Lease:IDisposable{NativeSupportPoseData owner;public Lease(NativeSupportPoseData p){owner=p;}public void Dispose(){if(owner){owner.Release();owner=null;}}}
 public IDisposable PinAndPrewarm(){Acquire();try{var ready=joints;return new Lease(this);}catch{Release();throw;}}
 sealed class Cursor{readonly byte[] b;int p;public Cursor(byte[] bytes){b=bytes;}[MethodImpl(MethodImplOptions.AggressiveInlining)]public int ReadInt32(){int n=BitConverter.ToInt32(b,p);p+=4;return n;}[MethodImpl(MethodImplOptions.AggressiveInlining)]public float ReadSingle(){float n=BitConverter.ToSingle(b,p);p+=4;return n;}public bool End=>p==b.Length;}
 Joint[] Decode(){if(!packedAsset)throw new InvalidOperationException("Native curve payload missing");using(var input=new MemoryStream(packedAsset.bytes,false))using(var zip=new DeflateStream(input,CompressionMode.Decompress))using(var output=new MemoryStream()){zip.CopyTo(output);var r=new Cursor(output.ToArray());if(!BitConverter.IsLittleEndian)throw new PlatformNotSupportedException("Native payload requires little-endian platform");if(r.ReadInt32()!=0x31434e4c)throw new InvalidDataException("Native lossless curve format invalid");int timeCount=r.ReadInt32();var times=new float[timeCount][];for(int t=0;t<timeCount;t++){times[t]=new float[r.ReadInt32()];for(int k=0;k<times[t].Length;k++)times[t][k]=r.ReadSingle();}var curves=new AnimationCurve[r.ReadInt32()];for(int c=0;c<curves.Length;c++){var pre=(WrapMode)r.ReadInt32();var post=(WrapMode)r.ReadInt32();var ts=times[r.ReadInt32()];var keys=new Keyframe[ts.Length];for(int k=0;k<keys.Length;k++){float value=r.ReadSingle(),it=r.ReadSingle(),ot=r.ReadSingle(),iw=r.ReadSingle(),ow=r.ReadSingle();var wm=(WeightedMode)r.ReadInt32();keys[k]=new Keyframe(ts[k],value,it,ot,iw,ow){weightedMode=wm};}curves[c]=new AnimationCurve(keys){preWrapMode=pre,postWrapMode=post};}int count=r.ReadInt32();if(count!=packedPaths.Length)throw new InvalidDataException("Native joint table invalid");var result=new Joint[count];for(int i=0;i<count;i++){var j=new Joint{path=packedPaths[i]};var a=new AnimationCurve[10];for(int n=0;n<10;n++){int index=r.ReadInt32();a[n]=index<0?null:curves[index];}j.px=a[0];j.py=a[1];j.pz=a[2];j.qx=a[3];j.qy=a[4];j.qz=a[5];j.qw=a[6];j.sx=a[7];j.sy=a[8];j.sz=a[9];result[i]=j;}if(!r.End)throw new InvalidDataException("Native payload trailing data");return result;}}
 public Transform[] Bind(Transform root){var paths=JointPaths;var targets=new Transform[paths.Length];for(int i=0;i<targets.Length;i++){targets[i]=paths[i].Length==0?root:root.Find(paths[i]);if(!targets[i])throw new InvalidOperationException("Native original path absent "+paths[i]);}return targets;}
 public void Apply(Transform[] targets,float seconds){var js=joints;for(int i=0;i<js.Length;i++){var j=js[i];var t=targets[i];if(j.px!=null)t.localPosition=new Vector3(j.px.Evaluate(seconds),j.py.Evaluate(seconds),j.pz.Evaluate(seconds));if(j.qx!=null)t.localRotation=Quaternion.Normalize(new Quaternion(j.qx.Evaluate(seconds),j.qy.Evaluate(seconds),j.qz.Evaluate(seconds),j.qw.Evaluate(seconds)));if(j.sx!=null)t.localScale=new Vector3(j.sx.Evaluate(seconds),j.sy.Evaluate(seconds),j.sz.Evaluate(seconds));}}
}
